CREATE TABLE IF NOT EXISTS public.res_country
(
    id serial NOT NULL,
    address_view_id integer,
    currency_id integer,
    phone_code integer,
    create_uid integer,
    write_uid integer,
    code character varying(2) COLLATE pg_catalog."default" NOT NULL,
    name_position character varying COLLATE pg_catalog."default",
    name jsonb NOT NULL,
    vat_label jsonb,
    address_format text COLLATE pg_catalog."default",
    state_required boolean,
    zip_required boolean,
    create_date timestamp without time zone,
    write_date timestamp without time zone,
    CONSTRAINT res_country_pkey PRIMARY KEY (id),
    CONSTRAINT res_country_code_uniq UNIQUE (code),
    CONSTRAINT res_country_name_uniq UNIQUE (name)
);

COMMENT ON TABLE public.res_country
    IS 'Country';

COMMENT ON COLUMN public.res_country.address_view_id
    IS 'Input View';

